@layer components {
  :where([data-control-family="alert"][data-slot="root"]) {
    --cui-alert-radius: var(--radius-panel);
    --cui-alert-background: var(--card);
    --cui-alert-border-color: var(--border);
    --cui-alert-shadow: none;
    --cui-alert-foreground: var(--card-foreground);
    --cui-alert-description-foreground: var(--muted-foreground);
    --cui-alert-border-width: var(--control-rim-width);
    --cui-alert-padding: calc(var(--spacing) * 3);
    --cui-alert-padding-inline: calc(var(--spacing) * 4);
    --cui-alert-gap: calc(var(--spacing) * 0.5);
    --cui-alert-icon-gap: calc(var(--spacing) * 3);
    --cui-alert-icon-size: calc(var(--spacing) * 4);
    --cui-alert-font-size: var(--text-body);
    --cui-alert-title-font-weight: var(--font-weight-medium);
    --cui-alert-description-gap: var(--spacing);
    --_alert-foreground: var(--cui-alert-foreground);
    --_alert-border-color: var(--cui-alert-border-color);
    --_alert-description-foreground: var(--cui-alert-description-foreground);
    --_alert-action-offset: var(--cui-alert-icon-gap);
    grid-template-columns: 0 minmax(0, 1fr);
    row-gap: var(--cui-alert-gap);
    padding: var(--cui-alert-padding) var(--cui-alert-padding-inline);
    border: var(--cui-alert-border-width) solid var(--_alert-border-color);
    border-radius: var(--cui-alert-radius);
    background: var(--cui-alert-background);
    box-shadow: var(--cui-alert-shadow);
    color: var(--_alert-foreground);
    font-size: var(--cui-alert-font-size);
    line-height: var(--leading-normal);
    overflow-wrap: anywhere;
  }

  :where([data-control-family="alert"][data-slot="root"][data-tone="info"]) {
    --_alert-tone: var(--info);
    --_alert-tone-text: var(--info-text);
  }

  :where([data-control-family="alert"][data-slot="root"][data-tone="success"]) {
    --_alert-tone: var(--success);
    --_alert-tone-text: var(--success-text);
  }

  :where([data-control-family="alert"][data-slot="root"][data-tone="warning"]) {
    --_alert-tone: var(--warning);
    --_alert-tone-text: var(--warning-text);
  }

  :where([data-control-family="alert"][data-slot="root"][data-tone="danger"]) {
    --_alert-tone: var(--destructive);
    --_alert-tone-text: var(--destructive-text);
  }

  :where([data-control-family="alert"][data-slot="root"][data-tone]:not([data-tone="neutral"])) {
    --_alert-foreground: var(--_alert-tone-text);
    --_alert-border-color: oklch(from var(--_alert-tone) l c h / 0.5);
    --_alert-description-foreground: oklch(from var(--_alert-tone-text) l c h / 0.9);
  }

  :where([data-control-family="alert"][data-slot="root"]:has(> svg)) {
    grid-template-columns: var(--cui-alert-icon-size) minmax(0, 1fr);
    column-gap: var(--cui-alert-icon-gap);
    --_alert-action-offset: 0px;
  }

  :where([data-control-family="alert"][data-slot="root"]:has(> [data-slot="action"])) {
    grid-template-columns: 0 minmax(0, 1fr) auto;
  }

  :where([data-control-family="alert"][data-slot="root"]:has(> svg):has(> [data-slot="action"])) {
    grid-template-columns: var(--cui-alert-icon-size) minmax(0, 1fr) auto;
  }

  :where([data-control-family="alert"][data-slot="root"] > [data-slot="action"]) {
    margin-inline-start: var(--_alert-action-offset);
  }

  :where([data-control-family="alert"][data-slot="description"]) {
    gap: var(--cui-alert-description-gap);
    color: var(--_alert-description-foreground);
    font-size: var(--cui-alert-font-size);
    line-height: var(--leading-normal);
    text-wrap: pretty;
  }

  :where([data-control-family="alert"][data-slot="description"] p) {
    line-height: var(--leading-relaxed);
  }

  :where([data-control-family="alert"][data-slot="title"]) {
    font-weight: var(--cui-alert-title-font-weight);
    letter-spacing: var(--tracking-tight);
    text-wrap: balance;
  }

  :where([data-control-family="alert"][data-slot="root"] > svg) {
    color: currentcolor;
    inline-size: var(--cui-alert-icon-size);
    block-size: var(--cui-alert-icon-size);
    margin-block-start: max(0px, calc((1lh - var(--cui-alert-icon-size)) / 2));
  }
}

@property --cui-alert-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

